CREATE TABLE abnormal_returns(event_id VARCHAR, ticker VARCHAR, day_offset INTEGER, date DATE NOT NULL, actual_return DOUBLE NOT NULL, expected_return DOUBLE NOT NULL, abnormal_return DOUBLE NOT NULL, PRIMARY KEY(event_id, ticker, day_offset));;
CREATE TABLE companies(ticker VARCHAR PRIMARY KEY, company_name VARCHAR NOT NULL, exchange VARCHAR, sector VARCHAR, industry VARCHAR, country VARCHAR, relationship_type VARCHAR NOT NULL, updated_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE correlations(ticker VARCHAR, reference_ticker VARCHAR, pearson_correlation DOUBLE, pearson_p_value DOUBLE, pearson_ci_low DOUBLE, pearson_ci_high DOUBLE, spearman_correlation DOUBLE, spearman_p_value DOUBLE, beta DOUBLE, alpha DOUBLE, r_squared DOUBLE, beta_p_value DOUBLE, sample_size INTEGER NOT NULL, computed_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, PRIMARY KEY(ticker, reference_ticker));;
CREATE TABLE documents(document_id VARCHAR PRIMARY KEY, company VARCHAR, event_id VARCHAR, document_date DATE, "source" VARCHAR, document_type VARCHAR NOT NULL, "text" VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, source_url VARCHAR);;
CREATE TABLE document_chunks(chunk_id VARCHAR PRIMARY KEY, document_id VARCHAR NOT NULL, chunk_index INTEGER NOT NULL, "text" VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE event_news(event_id VARCHAR, article_id VARCHAR, relevance_rank INTEGER NOT NULL, relevance_score DOUBLE NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, PRIMARY KEY(event_id, article_id));;
CREATE TABLE event_returns(event_id VARCHAR, ticker VARCHAR, event_date DATE NOT NULL, day_offset INTEGER, date DATE NOT NULL, daily_return DOUBLE, cumulative_return DOUBLE, PRIMARY KEY(event_id, ticker, day_offset));;
CREATE TABLE historical_events(event_id VARCHAR PRIMARY KEY, ticker VARCHAR NOT NULL, event_type VARCHAR, event_description VARCHAR, stla_return DOUBLE, sector_return DOUBLE, market_return DOUBLE, supplier_reaction DOUBLE, competitor_reaction DOUBLE, commodity_reaction DOUBLE, recovery_time_days INTEGER, computed_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE market_events(event_id VARCHAR PRIMARY KEY, event_date DATE NOT NULL, ticker VARCHAR NOT NULL, return DOUBLE NOT NULL, z_score DOUBLE, volume_z_score DOUBLE, volatility DOUBLE, severity VARCHAR NOT NULL, direction VARCHAR NOT NULL, detection_method VARCHAR NOT NULL, combined_score DOUBLE NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, market_return DOUBLE, sector_return DOUBLE, market_adjusted_return DOUBLE, sector_adjusted_return DOUBLE, classification VARCHAR, event_type VARCHAR, event_description VARCHAR, news_source VARCHAR);;
CREATE TABLE news(article_id VARCHAR PRIMARY KEY, title VARCHAR NOT NULL, "source" VARCHAR NOT NULL, "timestamp" TIMESTAMP WITH TIME ZONE, url VARCHAR NOT NULL, summary VARCHAR, mentioned_companies VARCHAR, ingested_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, source_kind VARCHAR, source_url VARCHAR, retrieved_at TIMESTAMP WITH TIME ZONE, content_sha256 VARCHAR, timestamp_status VARCHAR);;
CREATE TABLE price_data(ticker VARCHAR, date DATE, open DOUBLE NOT NULL, high DOUBLE NOT NULL, low DOUBLE NOT NULL, "close" DOUBLE NOT NULL, adj_close DOUBLE NOT NULL, volume BIGINT NOT NULL, "interval" VARCHAR, "source" VARCHAR NOT NULL, ingested_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, PRIMARY KEY(ticker, date, "interval"));;
CREATE TABLE price_features(ticker VARCHAR, date DATE, daily_return DOUBLE, log_return DOUBLE, rolling_return DOUBLE, rolling_mean DOUBLE, rolling_std DOUBLE, rolling_volatility DOUBLE, zscore DOUBLE, drawdown DOUBLE, volume_change DOUBLE, volume_zscore DOUBLE, lookback_window INTEGER NOT NULL, PRIMARY KEY(ticker, date));;
CREATE TABLE relationships(relationship_id VARCHAR PRIMARY KEY, source_entity VARCHAR NOT NULL, target_entity VARCHAR NOT NULL, target_entity_type VARCHAR NOT NULL, relationship_type VARCHAR NOT NULL, description VARCHAR, confidence VARCHAR NOT NULL, relationship_start DATE, relationship_end DATE, date_discovered DATE NOT NULL, "source" VARCHAR NOT NULL, evidence_url VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL, business_area VARCHAR, geographic_exposure VARCHAR, target_entity_ticker VARCHAR, evidence_date DATE, last_reviewed DATE, evidence_scope VARCHAR);;
CREATE TABLE relationship_evidence(evidence_id VARCHAR PRIMARY KEY, relationship_id VARCHAR NOT NULL, "source" VARCHAR NOT NULL, evidence_url VARCHAR NOT NULL, date_discovered DATE NOT NULL, description VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE rolling_correlations(ticker VARCHAR, reference_ticker VARCHAR, date DATE, rolling_correlation DOUBLE, lookback_window INTEGER NOT NULL, PRIMARY KEY(ticker, reference_ticker, date));;

